const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={douyin:'抖音',xiaohongshu:'小红书',unspecified:'未指定',source:'参考原文',analysis:'拆解报告',plan:'创作方案',drafts:'平台稿件',review:'发布前检查'};
const kinds={own_experience:'自有经历',third_party:'第三方参考',method:'方法材料',hypothetical:'假设场景'};
const modes={material:'采用获客素材',method:'方法讲解',product:'产品说明',interpret:'原视频例子解读',hypothetical:'明确标注的假设场景'};
const fields={title:'标题',cover_text:'封面文字',opening:'开场',script:'完整口播',caption:'笔记配文',cta:'结尾行动引导',subtitles:'重点字幕（每行一条）',topics:'话题（每行一条）'};
const pubFields={account_type:['账号类型',{unknown:'尚未确定',personal:'个人号',professional:'专业号',enterprise:'企业号'}],category:['内容行业',{unknown:'尚未确定',general:'普通内容',finance_insurance:'金融／保险',health:'健康／医疗'}],scene:['发布场景',{unknown:'尚未确定',ordinary:'日常笔记／视频',commercial:'商业合作内容',advertising:'广告投放'}],ai_use:['AI 参与方式',{unknown:'尚未确定',assisted:'AI 辅助创作',generated:'AI 生成',none:'没有使用 AI'}],rights:['作品及素材使用权',{unknown:'尚未确认',owned:'拥有使用权',authorized:'已取得授权',reference_only:'第三方参考，需确认许可'}],ai_confusable:['AI 内容是否可能被误认为真实拍摄／经历',{unknown:'尚未确定',no:'不会',yes:'可能会'}],scope:['本次检查范围',{platform_rules:'平台适用规则（目前规则覆盖不全）',available_text_rules:'仅已加载条款的文字检查（明确排除未加载规则）'}]};
let health,task=null,view='tasks',busy=false,selectedDrafts={},libraryEditing=null,currentProducts=[];
const phases={confirm_source:'等待核对并确认原文',confirm_brief:'等待确认创作方向',choose_material:'等待确认素材／写法',confirm_outline:'等待确认提纲',review_options:'等待填写发布信息并启动检查',choose_version:'查看报告并选择采用版本',wait_retry:'等待处理失败原因并恢复',extract_reference:'正在提取视频文字',analyze_structure:'正在执行八维拆解',recommend_materials:'正在评价素材',plan_outline:'正在生成提纲与材料对应',write_douyin:'正在生成抖音口播',write_xiaohongshu:'正在生成小红书口播',platform_review:'正在检查平台条款',revise_douyin:'正在修订抖音稿',revise_xiaohongshu:'正在修订小红书稿'};
const statuses={waiting:'等待操作',waiting_confirmation:'等待原文确认',report_ready:'拆解已保存',running:'正在执行',blocked:'等待补充或重试',interrupted:'执行中断，等待恢复'};
async function api(path,options={}){const r=await fetch('/api/acquisition'+path,{...options,headers:{'content-type':'application/json',...options.headers}});const b=await r.json();if(!r.ok||b.ok===false)throw new Error(`${b.error?.message||'请求失败'}（${b.error?.code||r.status}）`);return b.data;}
const post=(path,data)=>api(path,{method:'POST',body:JSON.stringify(data)});
function notice(t=''){ $('#notice').textContent=t; }
const input=(name,label,value='',type='text',required=true)=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const area=(name,label,value='',required=true,large=false)=>`<label>${esc(label)}<textarea name="${name}" ${required?'required':''} ${large?'class="large"':''}>${esc(value)}</textarea></label>`;
const select=(name,label,options,value)=>`<label>${esc(label)}<select name="${name}">${Object.entries(options).map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const button=(action,text,more='',primary=false)=>`<button data-action="${action}" ${more} class="${primary?'primary':''}">${text}</button>`;
const card=(title,body)=>`<section class="card"><h2>${title}</h2>${body}</section>`;
const submit=text=>`<button class="primary" type="submit">${text}</button>`;
function setTitle(title,crumb){$('#page-title').textContent=title;$('#breadcrumb').textContent='内容获客 / '+crumb;$('#navigation').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
async function tasksList(){const list=await api('/tasks');$('#task-list').innerHTML=list.map(t=>`<button class="task-link ${task?.id===t.id?'active':''}" data-task="${t.id}">${esc(t.title)}<small>${esc(names[t.stage]||t.stage)} · ${esc(statuses[t.status]||t.status)} · ${new Date(t.updated_at).toLocaleString('zh-CN')}</small></button>`).join('')||'<p class="muted">尚无任务</p>';}
async function loadTask(id){task=await api('/tasks/'+id);view='tasks';history.replaceState(null,'','?task='+id);selectedDrafts={};renderTask();await tasksList();}
async function command(action,data={}){if(!task)throw new Error('请先选择任务');const t=await post(`/tasks/${task.id}/command`,{action,command_id:crypto.randomUUID(),expected_revision:task.revision,...data});task=t;renderTask();await tasksList();return t;}
async function guarded(fn){if(busy)return;busy=true;notice('正在执行。确认输入和已完成产物会保存；模型调用期间可查看任务进度。');document.querySelectorAll('form button[type=submit],button[data-action]').forEach(b=>{if(b.dataset.action!=='stop_batch')b.disabled=true;});try{await fn();notice();}catch(e){notice(e.message);}finally{busy=false;document.querySelectorAll('button:disabled').forEach(b=>b.disabled=false);}}
function newTask(){task=null;view='tasks';history.replaceState(null,'',location.pathname);setTitle('新建内容获客任务','选择入口');$('#content').innerHTML=card('参考内容创作',`<p class="muted">输入一篇参考文字，或选择一条抖音／小红书链接。链接提取成功后，你仍需核对并确认文字范围。</p><form id="create-reference">${input('title','任务名称')}${select('input_kind','输入方式',{text:'粘贴已识别文字／文章',link:'粘贴平台分享链接'},'text')}${area('text','参考文字','',false,true)}${area('share_text','链接或完整分享文本','',false)}<p class="muted">多条分享链接会展开供你选一条；每任务采用一个参考作品。视频提取：${health?.extractor_configured?'服务已配置，仍需实际提取与核对':'尚未配置独立提取服务，可改用已识别文字'}</p>${submit('保存并进入原文确认')}</form>`)+card('已有稿件直接检查',`<p>这条入口跳过拆解、推荐与提纲，只检查你提交的文字字段。</p><form id="create-review">${input('title','任务名称')}${select('platform','目标平台',{douyin:'抖音',xiaohongshu:'小红书'},'douyin')}${input('draft_title','稿件标题','', 'text',false)}${area('script','完整口播稿','',true,true)}<label class="check"><input type="checkbox" name="ai_generated">这份原稿使用了 AI</label>${submit('保存稿件并填写发布信息')}</form>`);}
function commonTask(){const w=task.workflow,stageIndex=['source','analysis','plan','drafts','review'].indexOf(w.stage),usage=task.runs.reduce((s,r)=>s+(r.estimated_usd??0),0);return `<div class="steps">${['source','analysis','plan','drafts','review'].map((s,i)=>`<div class="${i===stageIndex?'active':''}">${i+1}. ${names[s]}</div>`).join('')}</div><div class="row"><span class="tag">${esc(phases[w.next]||w.next)}</span><span class="tag">材料轮次 ${w.epoch}</span><span class="muted">${task.runs.length} 次模型请求 · 估算 $${(task.budget_usage?.estimated_usd??usage).toFixed(5)}（含失败预留，非账单）</span></div><div class="toolbar">${button('save','保存当前进度')}${task.confirmed_text?button('back','返回原文确认','data-to="source"'):''}${task.report?button('back','返回创作方向','data-to="brief"'):''}${w.brief?button('back','返回素材／写法','data-to="materials"'):''}${w.outline?button('back','返回提纲','data-to="outline"'):''}${button('refresh_task','刷新任务')}${task.status==='running'&&['platform_review','revise_douyin','revise_xiaohongshu'].includes(w.next)?button('stop_batch','停止本批次'):''}</div>${task.error?`<div class="banner error"><strong>${esc(task.error.code)}</strong><br>${esc(task.error.message)}<br>失败节点：${esc(task.error.node||w.retry_node||'执行恢复')}</div>`:''}${task.status==='running'?'<div class="banner">节点正在执行；结果保存后会进入下一步或等待确认。</div>':''}`;}
function sourceForm(){return card('核对原文并确认采用范围',`<p>全文采用：不删文字。删减：只删除原文字。修正：允许修改识别错字，修改后的文字会另行记录。</p>${task.workflow.source?.url?`<p>参考来源：<a target="_blank" rel="noopener" href="${esc(task.workflow.source.url)}">打开参考作品</a></p>`:''}<form id="confirm-source">${select('mode','采用方式',{full:'采用全文',trimmed:'删减后采用',edited:'修正后采用'},'full')}${area('text','原文预览／采用文字',task.original_text,true,true)}${submit('确认范围并执行八维拆解')}</form>`);}
function reportView(){const r=task.report;if(!r)return '';return card('八维拆解报告',`<p>${esc(r.content.summary)}</p><p class="muted">依据所标原句分析；“可能作用”属于推测，不代表传播效果已验证。</p><div class="grid">${r.content.dimensions.map(d=>`<div class="subcard"><h3>${esc(d.name)}</h3><span class="tag">${({present:'有文字依据',not_provided:'文字未提供',not_applicable:'不适用'})[d.status]}</span><p>${esc(d.observation)}</p>${d.evidence.map(e=>`<blockquote>${esc(e.paragraph_id)}：${esc(e.quote)}</blockquote>`).join('')}<p><strong>可能作用：</strong>${esc(d.possible_effect)}</p><p><strong>迁移方法：</strong>${esc(d.migration)}</p><p><strong>限制：</strong>${esc(d.limitations)}</p></div>`).join('')}</div><details><summary>可复用方法、替换项及所需材料</summary><pre>${esc(JSON.stringify({方法:r.content.reusable_methods,替换项:r.content.replace_items,所需材料:r.content.required_materials},null,2))}</pre></details><a href="/api/acquisition/tasks/${task.id}/report.json">导出拆解报告 JSON</a>`);}
function briefForm(){const w=task.workflow,b=w.brief||task.report?.content.brief_suggestion||{};return card('确认本次创作方向',`<p>这里决定新稿写什么、说给谁听，以及希望观众下一步做什么。模型建议只是预填，提交后才成为本次确认条件。</p><form id="confirm-brief"><div class="grid">${input('topic','主题：这篇讲什么',b.topic)}${input('audience','受众：谁处于什么阶段、有何问题',b.audience)}${area('claim','观点：希望观众接受的具体判断',b.claim)}${area('goal','目的：希望观众采取的具体行动',b.goal)}</div><div class="grid three">${input('duration_seconds','目标口播时长（秒）',b.duration_seconds||60,'number')}${input('chars_per_minute','参考语速（每分钟字数）',b.chars_per_minute||240,'number')}${input('tone','表达语气',b.tone||'自然、具体、克制')}</div><div class="row"><label class="check"><input type="checkbox" name="douyin" ${(b.platforms||['douyin','xiaohongshu']).includes('douyin')?'checked':''}>抖音视频口播</label><label class="check"><input type="checkbox" name="xiaohongshu" ${(b.platforms||['douyin','xiaohongshu']).includes('xiaohongshu')?'checked':''}>小红书视频口播</label><label class="check"><input type="checkbox" name="uses_product" ${b.uses_product?'checked':''}>会讲自己的具体产品／参数</label></div><p>素材检索范围：</p><div class="row">${Object.entries(kinds).map(([k,v])=>`<label class="check"><input type="checkbox" name="kind_${k}" ${(b.source_kinds||Object.keys(kinds)).includes(k)?'checked':''}>${v}</label>`).join('')}</div>${submit('确认创作方向并推荐素材')}</form>`);}
async function selectionView(){const w=task.workflow,r=w.recommendations||{items:[]},products=await api('/products');currentProducts=products;if(task.workflow.next!=='choose_material')return;
 $('#phase-content').innerHTML=card('选择获客素材或确定写法',`<p>库内符合筛选条件 ${r.eligible_library_count??0} 份；本次最多评价 12 份，实际评价 ${r.reviewed_candidates??0} 份。按问题 30%、受众 25%、行动 20%、证据 15%、结构 10% 计算分数，达到 50 分者取前五。</p>${r.items.length?r.items.map((m,i)=>`<div class="subcard"><h3>${i+1}. ${esc(m.title)} <span class="badge-number">${m.score.toFixed(1)}</span></h3><p>${esc(kinds[m.kind])} · 素材 v${m.version} · 来源 ${esc(m.source)}</p><p><strong>匹配：</strong>${esc(m.reason)}<br><strong>差异：</strong>${esc(m.differences)}<br><strong>用法：</strong>${esc(m.intended_use)}<br><strong>限制：</strong>${esc(m.limitations)}</p>${m.evidence.map(e=>`<blockquote>${esc(e)}</blockquote>`).join('')}<label class="check"><input type="radio" name="candidate" value="${m.id}" data-version="${m.version}">选择此素材版本</label><details><summary>全文</summary><div class="text">${esc(m.content)}</div></details></div>`).join(''):'<div class="banner warning">本次没有达到要求的候选。系统不会补造五个案例。你可以修改筛选条件后重新推荐，或明确选择下列不使用真实客户案例的写法。</div>'}<div class="toolbar">${button('recommend_again','重新推荐')}${button('back','修改主题／受众／筛选范围','data-to="brief"')}</div><form id="select-material">${select('mode','本次写法',modes,r.items.length?'material':'method')}<p class="muted">方法讲解：讲步骤和判断；产品说明：讲所选产品资料；原例解读：保留原作者与来源；假设场景：全稿标明假设，不能说成真实客户。</p>${area('hypothetical_text','假设场景的条件与描述（选假设场景时必填）','',false)}${w.brief.uses_product?select('product','确认产品版本',Object.fromEntries([['','请选定产品资料版本'],...products.filter(p=>p.available).map(p=>[p.id+':'+p.version,p.name+' / '+p.version_label+' / 资料v'+p.version])]),''):'<p class="muted">本次未勾选具体产品，不要求产品资料，也不能带入参考视频的收益数字。</p>'}<div id="product-preview"></div>${submit('确认素材／写法，生成提纲与材料对应')}</form><details><summary>全部候选评价</summary><pre>${esc(JSON.stringify(r.evaluations||[],null,2))}</pre></details>`);
}
function outlineView(){const o=task.workflow.outline;if(!o)return '';const materials=task.workflow.selection?.materials||[];return card('提纲与材料对应',`<p>${esc(o.summary)}</p><div class="banner ${o.ready?'':'warning'}">${o.ready?'每段有材料引用且未报出缺项，等待你确认提纲。':'暂不能生成稿件：以下段落仍有缺项或材料冲突。'}</div>${o.conflicts.map(c=>`<p class="error">材料冲突：${esc(c)}</p>`).join('')}<table><thead><tr><th>段落与目的</th><th>准备表达的内容</th><th>材料与缺失项</th></tr></thead><tbody>${o.paragraphs.map(p=>`<tr><td>${esc(p.id)}<br>${esc(p.purpose)}<p class="muted">结构迁移：${esc(p.reference_function)}</p></td><td>${esc(p.content_plan)}</td><td>${p.material_refs.map(r=>`<blockquote>${esc(materials.find(m=>m.id===r.material_id)?.id||r.material_id)} v${r.version}<br>${esc(r.quote)}</blockquote>`).join('')}${p.required_product_keys.length?'<p>产品参数：'+esc(p.required_product_keys.join('、'))+'</p>':''}${p.missing_fields.map(f=>`<p class="error">缺少：${esc(f)}</p>`).join('')}</td></tr>`).join('')}</tbody></table><div class="toolbar">${o.ready?button('confirm_outline','确认当前提纲，生成所选平台口播','',true):''}${button('back','换素材／写法','data-to="materials"')}${button('back','修改观点，缩小主张范围','data-to="brief"')}</div><details><summary>修改提纲、删除无材料支撑的段落</summary><p>编辑下面 JSON 的段落目的、内容计划，或删除整段；重新提交后由 B 节点核对材料对应。引用必须保留真实材料 ID、版本及逐字原句，不能直接把缺项改成空数组来跳过检查。</p><form id="edit-outline">${area('outline','提纲 JSON',JSON.stringify({summary:o.summary,paragraphs:o.paragraphs,conflicts:o.conflicts},null,2),true,true)}${submit('保存编辑并重新核对材料')}</form></details>`);}
function draftView(){const w=task.workflow;if(!task.drafts.length)return '';return card('分平台稿件与历史版本',`${w.target_platforms.map(p=>{
 const drafts=task.drafts.filter(d=>d.platform===p).slice().reverse();if(!drafts.length)return `<p>${names[p]}尚未生成；另一平台的成功稿件会保留。</p>`;
 const chosen=selectedDrafts[p]||w.current_drafts[p]||drafts[0].id,d=drafts.find(d=>d.id===chosen)||drafts[0];
 const parent=d.parent_id?task.drafts.find(x=>x.id===d.parent_id):null,current=w.current_drafts[p]===d.id;
 const b=d.source.brief||(d.epoch===w.epoch?w.brief:null),characters=d.fields.script.replace(/\s/g,'').length,estimatedSeconds=b?Math.round(characters/b.chars_per_minute*60):null;
 const review=task.reviews.filter(r=>r.draft_id===d.id).at(-1);
 return `<div class="subcard"><div class="row"><h3>${names[p]}</h3><span class="tag ${current?'':'warn'}">${current?'本轮当前稿':'历史版本'} / v${d.version} / 材料轮次 ${d.epoch}</span><select data-draft-platform="${p}">${drafts.map(x=>`<option value="${x.id}" ${d.id===x.id?'selected':''}>v${x.version} · ${esc(x.kind)} · ${new Date(x.created_at).toLocaleString('zh-CN')}</option>`).join('')}</select></div><p class="muted">${estimatedSeconds!=null?`口播 ${characters} 字符；按 ${b.chars_per_minute} 字符／分钟估算 ${estimatedSeconds} 秒，目标 ${b.duration_seconds} 秒。${estimatedSeconds>b.duration_seconds*1.2?'篇幅超出目标，需要压缩或调整目标时长。':''}`:'现稿未设置语速，不估算时长。'}</p><p class="muted">${review?review.current?'有匹配当前稿件／发布信息／规则版本的检查报告':'报告已过期或对应历史版本，不能用于当前稿':'此版本尚未检查'}</p><form class="edit-draft" data-platform="${p}" data-id="${d.id}"><div class="grid">${input('title',fields.title,d.fields.title,'text',false)}${input('cover_text',fields.cover_text,d.fields.cover_text,'text',false)}${area('opening',fields.opening,d.fields.opening,false)}${area('cta',fields.cta,d.fields.cta,false)}</div>${area('script',fields.script,d.fields.script,true,true)}${p==='xiaohongshu'?area('caption',fields.caption,d.fields.caption,false):''}<div class="grid">${area('subtitles',fields.subtitles,d.fields.subtitles.join('\n'),false)}${area('topics',fields.topics,d.fields.topics.join('\n'),false)}</div>${current&&['review_options','choose_version'].includes(w.next)?submit('保存为新版本（旧版保留；检查需重做）'):''}</form>${parent?`<details class="diff"><summary>修订前后逐字段对照</summary>${Object.keys(fields).filter(k=>JSON.stringify(d.fields[k])!==JSON.stringify(parent.fields[k])).map(k=>`<h4>${fields[k]}</h4><div class="grid"><blockquote>原版本 v${parent.version}\n${esc(Array.isArray(parent.fields[k])?parent.fields[k].join('\n'):parent.fields[k])}</blockquote><blockquote>本版本 v${d.version}\n${esc(Array.isArray(d.fields[k])?d.fields[k].join('\n'):d.fields[k])}</blockquote></div>`).join('')||'<p>字段内容未改变。</p>'}</details>`:''}<div class="toolbar">${button('copy_draft','复制此版口播',`data-id="${d.id}"`)}<a href="/api/acquisition/tasks/${task.id}/drafts/${d.id}/export?format=md">导出此版 Markdown 及检查记录</a><a href="/api/acquisition/tasks/${task.id}/drafts/${d.id}/export?format=json">导出此版 JSON</a></div></div>`;
 }).join('')}`);}
function publicationForm(){const w=task.workflow;return card('发布信息与检查范围',`<p>审核只引用该平台已加载的官方条款。账号、行业、合作场景及作品使用权决定条款是否适用；“尚未确定”会成为待补信息，不能当成检查通过。</p><form id="start-review">${w.target_platforms.map(p=>`<h3>${names[p]}</h3><div class="grid">${Object.entries(pubFields).map(([k,[label,opts]])=>select(p+'_'+k,label,opts,w.publication?.[p]?.[k]||(k==='scope'?'platform_rules':'unknown'))).join('')}</div>${area(p+'_additional_information','补充发布信息：如职业资质、素材授权、AI 标识位置（用户声明，非核验证件）',w.publication?.[p]?.additional_information||'',false)}`).join('')}<div class="banner warning">目前未加载完整行业、广告及平台细则。“平台适用规则”范围会显示检查未完成；你可明确选择“仅已加载条款的文字检查”，其结果仍不等同于平台审核通过。</div>${select('max_revisions','本批次每平台自动修订次数上限（你提交后才启动）',{'0':'0 次：只检查，交给我修改','1':'最多 1 次修订并复检','2':'最多 2 次修订并复检'},'2')}${submit('按所选范围开始检查与修订')}</form>`);}
function reviewsView(){const w=task.workflow;if(!task.reviews.length)return '';const latest=w.target_platforms.map(p=>task.reviews.find(r=>r.id===w.current_reviews[p])).filter(Boolean);return card('检查报告与停止原因',`${latest.map(r=>`<div class="subcard"><h3>${names[r.platform]} / ${esc(r.payload.result)} <span class="tag ${r.current?'':'warn'}">${r.current?'对应当前版本':'已过期'}</span></h3><p>${esc(r.payload.summary)}</p><div class="banner warning">${esc(r.payload.stop_reason||'仍在修订循环中')}<br>全平台规则覆盖：未完成；本次声明范围：${r.payload.coverage.requested_scope_complete?'已完成':'未完成'}。修订 ${r.payload.revision_count} 次。</div><h4>需补充的发布信息</h4>${r.payload.coverage.information_gaps.length?`<pre>${esc(JSON.stringify(r.payload.coverage.information_gaps,null,2))}</pre>`:'<p>未报出发布信息缺项。</p>'}<h4>尚未覆盖的规则</h4>${r.payload.coverage.platform_gaps.map(g=>`<p>${esc(g.owner)}：${esc(g.action)}</p>`).join('')}${r.payload.issues.map(i=>`<div class="subcard"><strong>${esc(i.field)} / ${esc(i.rule_id)} / ${({revise:'可改文字',information:'需补信息',advice:'建议'})[i.action]}</strong><blockquote>${esc(i.quote)}</blockquote><p>${esc(i.explanation)}</p><p>修改建议：${esc(i.suggestion)}</p><p>${i.requires_direction_change?'需返回创作方案确认改变方向。':''}<a target="_blank" rel="noopener" href="${esc(i.source_url)}">${esc(i.clause)}</a></p></div>`).join('')}<details><summary>本次送检条款逐项结果</summary><table>${r.payload.checks.map(c=>`<tr><td>${esc(c.rule_id)}</td><td>${esc(c.result)}</td><td>${esc(c.explanation)}</td></tr>`).join('')}</table></details><p class="muted">稿件 hash：${esc(r.draft_hash)}<br>规则版本：${esc(r.payload.coverage.snapshot.version)}；记录时间：${esc(r.created_at)}。画面／音频／资质证件未检查。</p></div>`).join('')}${w.next==='choose_version'?`<form id="adopt">${w.target_platforms.map(p=>select(p,'选择采用的'+names[p]+'稿件版本',Object.fromEntries(task.drafts.filter(d=>d.platform===p&&d.epoch===w.epoch).map(d=>[d.id,'v'+d.version+' / '+d.kind])),w.adopted[p]||w.current_drafts[p])).join('')}${submit('记录采用版本')}</form>${Object.keys(w.adopted).length?'<p class="banner">采用版本已记录。导出时会带上该版本对应的报告，并标明报告是否过期或检查未完成。</p>':''}`:''}`);}
function recovery(){return card('恢复当前节点',`<p>仅重试失败节点；已保存的其他平台稿件和此前产物不会重新调用模型生成。</p><div class="toolbar">${button('retry','重试／恢复执行','',true)}</div>${task.workflow.retry_node==='extract_reference'?`<form id="supply-text">${area('text','粘贴已识别的完整口播文字','',true,true)}${submit('保存文字并核对范围')}</form><form id="change-link">${area('share_text','替换参考分享链接')}${submit('保存链接并重试提取')}</form>`:''}<details><summary>调整本任务调用预算</summary><p>达到上限会暂停；费用按费率快照估算，不是供应商账单。增加预算不会自动重试，保存后需要点击恢复。</p><form id="set-budget"><div class="grid">${input('max_calls','模型请求上限（1–60）',task.workflow.budget.max_calls,'number')}${input('max_estimated_usd','估算美元上限（0.01–5）',task.workflow.budget.max_estimated_usd,'text')}</div>${submit('保存预算上限')}</form></details>`);}
function renderTask(){if(!task)return newTask();setTitle(task.title,names[task.workflow.stage]);const w=task.workflow;let body=commonTask();
 if(w.next==='confirm_source')body+=sourceForm();
 if(['confirm_brief','choose_material','confirm_outline'].includes(w.next))body+=reportView();
 if(w.next==='confirm_brief')body+=briefForm();
 if(w.next==='choose_material'){body+='<div id="phase-content">正在读取本次推荐与产品版本…</div>';}
 if(w.next==='confirm_outline')body+=outlineView();
 if(task.drafts.length)body+=draftView();
 if(['review_options','choose_version'].includes(w.next))body+=publicationForm();
 if(task.reviews.length)body+=reviewsView();
 if(w.next==='wait_retry'||task.status==='interrupted')body+=recovery();
 body+=`<details class="card"><summary>这一步由谁执行，为什么暂停</summary><p>Graph 是程序定义的执行图，按当前节点、确认记录和结构化结果选择下一节点。当前：${esc(w.next)}；AI 不决定跳过你的确认。</p><pre>${esc(JSON.stringify({current_node:w.next,last_action:w.last_command,retry_node:w.retry_node,stop_reasons:w.stop_reasons},null,2))}</pre><table>${task.events.slice(-12).reverse().map(e=>`<tr><td>${esc(e.node)}</td><td>${esc(e.action)}</td><td>${new Date(e.created_at).toLocaleTimeString('zh-CN')}</td></tr>`).join('')}</table><h3>模型请求、用量与实际耗时</h3><table><tr><th>岗位与状态</th><th>输入／输出 tokens</th><th>请求至响应解析及校验耗时</th><th>估算美元，非账单</th></tr>${task.runs.map(r=>`<tr><td>${esc(r.node_name||'旧版 A')} / ${esc(r.status)}</td><td>${r.usage?.prompt_tokens??'未知'} / ${r.usage?.completion_tokens??'未知'}</td><td>${(r.elapsed_ms/1000).toFixed(3)} 秒</td><td>${r.estimated_usd!=null?'$'+r.estimated_usd.toFixed(5):'旧记录：按用量或未知上界估算'}</td></tr>`).join('')}</table><p>本任务上限 ${w.budget.max_calls} 次请求、估算 $${w.budget.max_estimated_usd}。</p><h3>保存的原文与产物历史</h3>${task.artifacts.map(a=>`<p><a target="_blank" rel="noopener" href="/api/acquisition/tasks/${task.id}/artifacts/${a.id}">${esc(a.kind)} / ${esc(a.scope)} / 材料轮次 ${a.epoch} / ${esc(a.created_at)}</a></p>`).join('')}</details>`;
 $('#content').innerHTML=body;if(w.next==='choose_material')selectionView().catch(e=>notice(e.message));}
async function materialsPage(){view='materials';setTitle('获客素材库','独立素材与版本');const list=await api('/materials');const old=libraryEditing?list.find(m=>m.id===libraryEditing):null;$('#content').innerHTML=card('录入获客素材',`<p>这张库独立于销售工作台。每次修改生成新版本，任务采用时保留具体版本。第三方参考不能自动变成“我的客户”。</p><form id="material-form" data-id="${old?.id||''}" data-version="${old?.version||''}">${input('title','素材标题',old?.title)}<div class="grid">${select('kind','材料类型',kinds,old?.kind||'method')}${select('rights','使用权状态',{unknown:'尚未确认（不参与推荐）',owned:'我拥有使用权',authorized:'已获得授权',reference_only:'只作第三方参考'},old?.rights||'unknown')}</div>${input('source','来源：记录、文档名称或作品链接',old?.source)}${area('content','完整素材文字',old?.content,true,true)}${input('tags','检索标签（用逗号分隔）',old?.tags?.join('，')||'','text',false)}<label class="check"><input name="available" type="checkbox" ${old?.available!==false?'checked':''}>允许进入检索</label>${submit(old?'保存新版本':'保存获客素材')}</form>`)+card('已有素材',list.length?list.map(m=>`<div class="subcard"><h3>${esc(m.title)} / v${m.version}</h3><p>${esc(kinds[m.kind])} · ${esc(m.rights)} · ${m.available?'可检索':'已停用'}</p><p>${esc(m.source)}</p><details><summary>查看全文</summary><div class="text">${esc(m.content)}</div></details>${button('edit_material','修改为新版本',`data-id="${m.id}"`)}</div>`).join(''):'<p class="empty">素材库目前为空。创作流程仍可选择方法讲解等四种写法。</p>');}
async function productsPage(){view='products';setTitle('产品资料库','产品条件与参数版本');const list=await api('/products');const old=libraryEditing?list.find(p=>p.id===libraryEditing):null;$('#content').innerHTML=card('录入产品资料',`<p>产品数字取自这里确认的版本。每项参数填写值、单位、保证／演示性质和资料来源，不从参考视频复制收益率。</p><form id="product-form" data-id="${old?.id||''}" data-version="${old?.version||''}"><div class="grid">${input('name','产品名称',old?.name)}${input('version_label','官方版本／计划日期',old?.version_label)}</div>${input('source','资料来源：文件名称、页码或官方链接',old?.source)}${area('conditions','适用条件、缴费方式及限制',old?.conditions)}${area('parameters','参数数组 JSON；不讲数字时可为空数组',JSON.stringify(old?.parameters||[],null,2),true,true)}<p class="muted">每项格式：key（英文唯一名）、label（名称）、value（值）、unit（单位）、nature（guaranteed / illustrated / other）、source（来源）。演示值在稿件原句中必须说明非保证性质。</p><label class="check"><input name="available" type="checkbox" ${old?.available!==false?'checked':''}>此版本可供采用</label>${submit(old?'保存新版本':'保存产品资料')}</form>`)+card('产品版本',list.length?list.map(p=>`<div class="subcard"><h3>${esc(p.name)} / ${esc(p.version_label)} / 资料 v${p.version}</h3><p>${esc(p.source)}</p><div class="text">${esc(p.conditions)}</div><pre>${esc(JSON.stringify(p.parameters,null,2))}</pre>${button('edit_product','修改为新版本',`data-id="${p.id}"`)}</div>`).join(''):'<p class="empty">尚未录入产品资料；方法讲解可以不选产品。</p>');}
async function rulesPage(){view='rules';setTitle('平台规则与检查边界','官方来源及适用范围');const data=await api('/rules');$('#content').innerHTML=card('规则快照 '+data.snapshot.version,`<div class="banner warning">${data.snapshot.limitations.map(esc).join('<br>')}</div><table><tr><th>官方来源</th><th>页面日期</th><th>核对方式</th></tr>${data.snapshot.sources.map(s=>`<tr><td><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)}</a></td><td>${esc(s.document_date||'页面未给出日期')}</td><td>${s.verification==='official_page'?'已读取官方页面正文':'已读取官方页面搜索快照，动态页面版本复核待完成'}</td></tr>`).join('')}</table>`)+card('已加载条款摘要',`<table><tr><th>ID / 平台</th><th>条款与内容</th><th>性质与场景</th></tr>${data.rules.map(r=>`<tr><td>${r.id}<br>${names[r.platform]}</td><td><a href="${esc(r.source_url)}" target="_blank" rel="noopener">${esc(r.clause)}</a><p>${esc(r.summary)}</p></td><td>${r.kind==='suggestion'?'建议：不作为自动改稿必选项':'要求'}<br>${r.scene==='commercial'?'仅商业合作内容':'全场景，仍按条款条件判断'}</td></tr>`).join('')}</table><p>缺规则的处理责任方是规则维护者。模型不能补造官方规则；发布信息缺失由你补充。当前规则不包含完整保险行业审核要求。</p>`);}
function graphSvg(){const nodes=[['输入链接／文字',60,30,'source'],['确认原文范围',60,125,'source'],['A · 八维拆解',60,220,'analysis'],['确认主题、受众、观点',60,315,'analysis'],['R · 评价候选，推荐前五',60,410,'plan'],['确认素材／写法／产品版本',60,505,'plan'],['B · 提纲与材料对应',390,505,'plan'],['确认提纲',390,410,'plan'],['C_DY · 抖音口播',390,315,'drafts'],['C_XHS · 小红书口播',390,220,'drafts'],['填写发布信息、启动检查',390,125,'review'],['D · 平台条款检查',720,125,'review'],['Graph 按报告字段分支',720,220,'review'],['对应 C 节点修订',720,315,'review'],['用户选择版本、导出',720,505,'review']];const arrows=[[200,90,200,125],[200,185,200,220],[200,280,200,315],[200,375,200,410],[200,470,200,505],[340,535,390,535],[530,505,530,470],[530,410,530,375],[530,315,530,280],[530,220,530,185],[670,155,720,155],[860,185,860,220],[860,280,860,315]];return `<svg viewBox="0 0 1080 670" role="img" aria-label="Graph、六个 AI 节点、确认点和修订循环"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#718f7f"/></marker></defs>${arrows.map(([x,y,a,b])=>`<path class="arrow" marker-end="url(#arrow)" d="M${x},${y} L${a},${b}"/>`).join('')}<path class="arrow" marker-end="url(#arrow)" d="M1000 345 H1040 V155 H1000"/><path class="arrow" marker-end="url(#arrow)" d="M1000 250 H1020 V535 H1000"/><text x="690" y="302" font-size="13">可改文字且未到上限 ↓</text><text x="730" y="480" font-size="13">检查完成／缺项／循环停止 → 选择版本</text><text x="790" y="425" font-size="14">最多修订两次；每次再 D 检查</text><text x="725" y="455" font-size="14">缺信息／规则：停下，说明责任与补充项</text>${nodes.map(([t,x,y,s])=>`<g class="node ${task?.workflow.stage===s?'active':''}"><rect x="${x}" y="${y}" width="280" height="60" rx="12"/><text x="${x+140}" y="${y+36}" text-anchor="middle">${t}</text></g>`).join('')}<text x="60" y="625" font-size="15">绿色表示当前阶段。主 Graph 控制箭头；框内任务由对应模型配置或工具执行。</text></svg>`;}
function teachPage(){view='teach';setTitle('看懂并查看这条工作流','Graph 与六个固定 AI 节点');$('#content').innerHTML=card('主 Graph：执行顺序、确认点与循环',graphSvg())+card('六个 AI 节点怎样调用',`<p>六个岗位配置共用 ${esc(health.model)}。每次只给当前岗位加载对应 Skill、材料与输出格式；没有自主 AI 中控，也没有六个常驻独立 Agent。</p><table><tr><th>节点</th><th>职责</th><th>加载 Skill</th></tr>${health.implemented_ai_nodes.map(n=>`<tr><td>${esc(n.id)}</td><td>${esc(n.name)}</td><td>${esc(n.skill_file)}</td></tr>`).join('')}</table><p>例如：你确认提纲后，程序调用 C_DY；它提交稿件后，程序调用 C_XHS。你提交发布信息后，程序调用 D。D 返回问题原句、规则 ID、能否只改文字，Graph 按这些字段决定修订、暂停或交给你选择版本。</p><p>恢复：任务、材料版本、稿件与报告存在 SQLite；Graph 的等待点存在独立检查点数据库。刷新页面不重新调用模型。</p>`)+card('成本、速度与停止条件',`<p>模型：${esc(health.model)}；模式：${esc(health.thinking_mode||'由适配器指定')}；提取配置：${health.extractor_configured?'已配置':'未配置'}。</p><p>每任务默认最多 24 次模型请求、估算 $0.10；每平台每批次最多修订 2 次。每次记录模型返回的 token 用量与实际耗时。速度以本任务记录为准，不能提前承诺固定秒数。</p><p>费用估算快照：${esc(health.rate_snapshot.date)}；按输入未缓存 $0.30／百万 token、缓存 $0.006／百万、输出 $1.20／百万保守计算。请求前预留一次调用上界；失败无完整用量时也预留，避免把不明账单当成免费。</p><details><summary>实际 Graph 的 Mermaid 源码</summary><pre>${esc(health.graph_mermaid)}</pre></details>`);}
$('#content').addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form),v=k=>String(f.get(k)||'');guarded(async()=>{
 switch(form.id){
 case 'create-reference':{let share=v('share_text');if(v('input_kind')==='link'){const links=await post('/links',{share_text:share});if(!links.length)throw new Error('分享文本中没有可用的抖音／小红书链接');if(links.length>1){$('#content').insertAdjacentHTML('afterbegin',card('先选一条参考链接',links.map(l=>button('pick_link',esc(l.url),`data-url="${esc(l.url)}"`)).join('<br>')));notice('请选择其中一条；你填写的任务信息仍保留。');return;}share=links[0].url;}task=await post('/tasks',{title:v('title'),input_kind:v('input_kind'),text:v('text'),share_text:share});history.replaceState(null,'','?task='+task.id);renderTask();await tasksList();break;}
 case 'create-review':task=await post('/tasks',{entry:'direct_review',title:v('title'),platform:v('platform'),ai_generated:f.has('ai_generated'),fields:{title:v('draft_title'),script:v('script')}});renderTask();history.replaceState(null,'','?task='+task.id);await tasksList();break;
 case 'confirm-source':await command('confirm',{mode:v('mode'),text:v('text')});break;
 case 'confirm-brief':await command('confirm_brief',{brief:{topic:v('topic'),audience:v('audience'),claim:v('claim'),goal:v('goal'),platforms:['douyin','xiaohongshu'].filter(p=>f.has(p)),duration_seconds:Number(v('duration_seconds')),chars_per_minute:Number(v('chars_per_minute')),tone:v('tone'),uses_product:f.has('uses_product'),source_kinds:Object.keys(kinds).filter(k=>f.has('kind_'+k))}});break;
 case 'select-material':{const selected=$('input[name=candidate]:checked'),prod=v('product').split(':');await command(v('mode')==='material'?'select_material':'select_mode',{mode:v('mode'),material_id:selected?.value,material_version:Number(selected?.dataset.version),hypothetical_text:v('hypothetical_text'),product_id:prod[0],product_version:Number(prod[1])});break;}
 case 'edit-outline':await command('edit_outline',{outline:JSON.parse(v('outline'))});break;
 case 'start-review':{const publication={};for(const p of task.workflow.target_platforms)publication[p]={...Object.fromEntries(Object.keys(pubFields).map(k=>[k,v(p+'_'+k)])),additional_information:v(p+'_additional_information')};await command('start_review',{publication,max_revisions:Number(v('max_revisions'))});break;}
 case 'adopt':await command('adopt',{draft_ids:Object.fromEntries(task.workflow.target_platforms.map(p=>[p,v(p)]))});break;
 case 'supply-text':await command('supply_text',{text:v('text')});break;
 case 'change-link':await command('change_link',{share_text:v('share_text')});break;
 case 'set-budget':await command('set_budget',{budget:{max_calls:Number(v('max_calls')),max_estimated_usd:Number(v('max_estimated_usd'))}});break;
 case 'material-form':await post('/materials'+(form.dataset.id?'/'+form.dataset.id:''),{expected_version:Number(form.dataset.version),data:{title:v('title'),kind:v('kind'),rights:v('rights'),source:v('source'),content:v('content'),tags:v('tags').split(/[,，]/).map(s=>s.trim()).filter(Boolean),available:f.has('available')}});libraryEditing=null;await materialsPage();break;
 case 'product-form':await post('/products'+(form.dataset.id?'/'+form.dataset.id:''),{expected_version:Number(form.dataset.version),data:{name:v('name'),version_label:v('version_label'),source:v('source'),conditions:v('conditions'),parameters:JSON.parse(v('parameters')),available:f.has('available')}});libraryEditing=null;await productsPage();break;
 default:if(form.classList.contains('edit-draft')){const d=task.drafts.find(d=>d.id===form.dataset.id),updated={...d.fields};for(const k of Object.keys(fields))if(f.has(k))updated[k]=['subtitles','topics'].includes(k)?v(k).split('\n').map(x=>x.trim()).filter(Boolean):v(k);updated.product_references=[];await command('edit_draft',{platform:form.dataset.platform,draft_id:d.id,fields:updated});}break;
 }
});});
$('#content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='pick_link'){const f=$('#create-reference');f.elements.share_text.value=b.dataset.url;f.requestSubmit();return;}
 if(a==='stop_batch'){(async()=>{try{task=await api('/tasks/'+task.id);await command(a);notice('停止请求已保存；正在进行的供应商调用不会被假定取消，其结果保存后停止。');}catch(err){notice(err.message);}})();return;}
 guarded(async()=>{if(a==='copy_draft'){const d=task.drafts.find(x=>x.id===b.dataset.id);await navigator.clipboard.writeText(d.fields.script);notice('此版本口播正文已复制。');}else if(a==='back')await command('back',{to:b.dataset.to});else if(a==='confirm_outline')await command(a,{outline_hash:await sha(JSON.stringify(task.workflow.outline))});else if(a==='refresh_task')await loadTask(task.id);else if(a==='pick_link'){const f=$('#create-reference');f.elements.share_text.value=b.dataset.url;f.requestSubmit();}else if(a==='edit_material'){libraryEditing=b.dataset.id;await materialsPage();}else if(a==='edit_product'){libraryEditing=b.dataset.id;await productsPage();}else await command(a);});
});
$('#content').addEventListener('change',e=>{if(e.target.name==='product'&&e.target.closest('#select-material')){const [id,version]=e.target.value.split(':'),p=currentProducts.find(x=>x.id===id&&x.version===Number(version));if($('#product-preview'))$('#product-preview').innerHTML=p?`<div class="subcard"><h3>将采用的产品资料：${esc(p.name)} / v${p.version}</h3><p>资料来源：${esc(p.source)}</p><div class="text">${esc(p.conditions)}</div><table>${p.parameters.map(x=>`<tr><td>${esc(x.label)}</td><td>${esc(x.value+x.unit)}</td><td>${esc(x.nature)}</td><td>${esc(x.source)}</td></tr>`).join('')}</table></div>`:'';}if(e.target.dataset.draftPlatform){selectedDrafts[e.target.dataset.draftPlatform]=e.target.value;renderTask();}});
async function sha(text){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
$('#navigation').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;libraryEditing=null;guarded(async()=>{switch(b.dataset.view){case 'tasks':view='tasks';task?renderTask():newTask();break;case 'materials':await materialsPage();break;case 'products':await productsPage();break;case 'rules':await rulesPage();break;case 'teach':teachPage();break;}});});
$('#task-list').addEventListener('click',e=>{const b=e.target.closest('[data-task]');if(b)guarded(()=>loadTask(b.dataset.task));});$('#new-task').onclick=()=>{if(!busy)newTask();};$('#refresh').onclick=()=>guarded(tasksList);
setInterval(async()=>{if(task&&view==='tasks'&&(busy||task.status==='running')){try{const latest=await api('/tasks/'+task.id);if(latest.revision!==task.revision){task=latest;renderTask();}}catch{}}},2500);
try{health=await api('/health');$('#health').textContent=health.model_configured?`${health.model} 已配置`:'模型待配置';await tasksList();const id=new URLSearchParams(location.search).get('task');if(id)await loadTask(id);else newTask();}catch(e){notice(e.message);$('#health').textContent='服务读取失败';}
